import heapq

class TopOfBook:
    def __init__(self):
        self.lv = {"B": {}, "S": {}}
        self.heap = {"B": [], "S": []}   # bids stored as -price

    def update(self, side, price, qty):
        book = self.lv[side]
        if qty == 0:
            book.pop(price, None)
        else:
            if price not in book:
                heapq.heappush(self.heap[side], -price if side == "B" else price)
            book[price] = qty

    def _best(self, side):
        h, book = self.heap[side], self.lv[side]
        while h:
            p = -h[0] if side == "B" else h[0]
            if p in book:
                return [p, book[p]]
            heapq.heappop(h)          # stale level
        return None

    def best_bid(self):
        return self._best("B")

    def best_ask(self):
        return self._best("S")

    def spread(self):
        b, a = self._best("B"), self._best("S")
        return None if b is None or a is None else a[0] - b[0]

