import heapq
from collections import deque

class OrderBook:
    def __init__(self):
        self.levels = {"B": {}, "S": {}}   # price -> deque of [id, qty]
        self.heaps = {"B": [], "S": []}    # bids as -price
        self.where = {}                    # id -> order entry [id, qty]

    def _key(self, side, price):
        return -price if side == "B" else price

    def _top(self, side):
        h, lv = self.heaps[side], self.levels[side]
        while h:
            price = -h[0] if side == "B" else h[0]
            q = lv.get(price)
            while q and q[0][1] == 0:
                q.popleft()
            if q:
                return price
            lv.pop(price, None)
            heapq.heappop(h)
        return None

    def add(self, order_id, side, price, qty):
        fills = []
        opp = "S" if side == "B" else "B"
        while qty > 0:
            best = self._top(opp)
            if best is None or (side == "B" and best > price) or (side == "S" and best < price):
                break
            q = self.levels[opp][best]
            o = q[0]
            t = min(qty, o[1])
            fills.append([o[0], best, t])
            o[1] -= t
            qty -= t
            if o[1] == 0:
                q.popleft()
                del self.where[o[0]]
        if qty > 0:
            lv = self.levels[side]
            if price not in lv:
                lv[price] = deque()
                heapq.heappush(self.heaps[side], self._key(side, price))
            entry = [order_id, qty]
            lv[price].append(entry)
            self.where[order_id] = entry
        return fills

    def cancel(self, order_id):
        e = self.where.pop(order_id, None)
        if e is None:
            return False
        e[1] = 0          # lazy delete
        return True

    def best_bid(self):
        return self._top("B")

    def best_ask(self):
        return self._top("S")

