    cout << (ok ? "PASS " : "FAIL ") << name << "  got " << got << "  want " << want << "\n";
    if (!ok) ++fails;
}

struct Fill { int restingId; int price; int qty; bool operator==(const Fill& o) const { return restingId==o.restingId && price==o.price && qty==o.qty; } };

struct OrderBook {
    struct Order { int id; int qty; };
    map<int, list<Order>, greater<int>> bids;   // best bid first
    map<int, list<Order>> asks;                 // best ask first
    struct Loc { char side; int price; list<Order>::iterator it; };
    unordered_map<int, Loc> index;

    template <class Book>
    void match(Book& book, bool isBuy, int price, int& qty, vector<Fill>& fills) {
        while (qty > 0 && !book.empty()) {
            auto lvl = book.begin();
            if (isBuy ? lvl->first > price : lvl->first < price) break;
            auto& q = lvl->second;
            while (qty > 0 && !q.empty()) {
                Order& o = q.front();
                int t = min(qty, o.qty);
                fills.push_back({o.id, lvl->first, t});
                o.qty -= t; qty -= t;
                if (o.qty == 0) { index.erase(o.id); q.pop_front(); }
            }
            if (q.empty()) book.erase(lvl);
        }
    }
    vector<Fill> add(int id, char side, int price, int qty) {
        vector<Fill> fills;
        if (side == 'B') match(asks, true, price, qty, fills);
        else             match(bids, false, price, qty, fills);
        if (qty > 0) {
            if (side == 'B') { auto& q = bids[price]; q.push_back({id, qty}); index[id] = {'B', price, prev(q.end())}; }
            else             { auto& q = asks[price]; q.push_back({id, qty}); index[id] = {'S', price, prev(q.end())}; }
        }
        return fills;
    }
    bool cancel(int id) {
        auto f = index.find(id);
        if (f == index.end()) return false;
        Loc l = f->second; index.erase(f);
        if (l.side == 'B') { auto& q = bids[l.price]; q.erase(l.it); if (q.empty()) bids.erase(l.price); }
        else               { auto& q = asks[l.price]; q.erase(l.it); if (q.empty()) asks.erase(l.price); }
        return true;
    }
    optional<int> bestBid() const { if (bids.empty()) return nullopt; return bids.begin()->first; }
    optional<int> bestAsk() const { if (asks.empty()) return nullopt; return asks.begin()->first; }
};

int main() {
    OrderBook ob;
    ob.add(1, 'S', 101, 5); ob.add(2, 'S', 101, 3);
    auto f = ob.add(3, 'B', 102, 6);
    check("fills", f, vector<Fill>{{1, 101, 5}, {2, 101, 1}});
    check("best ask after fill", ob.bestAsk(), optional<int>(101));
    check("cancel resting", ob.cancel(2), true);
    check("cancel twice", ob.cancel(2), false);
    check("book empty", ob.bestAsk().has_value(), false);
    return fails;
}

