from collections import deque

def vwap_window(trades, W):
    q, pq, qq, out = deque(), 0.0, 0.0, []
    for t, p, n in trades:
        q.append((t, p, n)); pq += p * n; qq += n
        while q and q[0][0] <= t - W:
            _, p0, n0 = q.popleft(); pq -= p0 * n0; qq -= n0
        out.append(pq / qq)
    return out

