class RingBuffer:
    def __init__(self, capacity):
        self.cap = capacity
        self.buf = [None] * capacity
        self.head = 0   # next slot to read  (consumer-owned)
        self.tail = 0   # next slot to write (producer-owned)

    def push(self, x):
        if self.tail - self.head == self.cap:
            return False
        self.buf[self.tail % self.cap] = x
        self.tail += 1          # C++: tail.store(t + 1, memory_order_release)
        return True

    def pop(self):
        if self.head == self.tail:
            return None
        x = self.buf[self.head % self.cap]
        self.head += 1          # C++: head.store(h + 1, memory_order_release)
        return x

    def size(self):
        return self.tail - self.head

