template <class T>
class SpscRing {
    vector<T> buf;
    const size_t cap;
    alignas(64) atomic<size_t> head{0};   // written by consumer
    alignas(64) atomic<size_t> tail{0};   // written by producer
public:
    explicit SpscRing(size_t capacity) : buf(capacity), cap(capacity) {}
    bool push(const T& x) {
        size_t t = tail.load(memory_order_relaxed);
        if (t - head.load(memory_order_acquire) == cap) return false;   // full
        buf[t % cap] = x;
        tail.store(t + 1, memory_order_release);                         // publish
        return true;
    }
    optional<T> pop() {
        size_t h = head.load(memory_order_relaxed);
        if (h == tail.load(memory_order_acquire)) return nullopt;        // empty
        T x = buf[h % cap];
        head.store(h + 1, memory_order_release);
        return x;
    }
};

