def _bs(S, K, r, s, T):
    N = lambda x: 0.5 * (1 + math.erf(x / math.sqrt(2)))
    d1 = (math.log(S / K) + (r + s * s / 2) * T) / (s * math.sqrt(T)); d2 = d1 - s * math.sqrt(T)
    return S * N(d1) - K * math.exp(-r * T) * N(d2)
def check(fn, args, got):
    S, K, r, s, T, n, seed = args
    ref = _bs(S, K, r, s, T)
    try: g = float(got)
    except Exception: return False, f"expected a number, got {got!r}"
    ok = abs(g - ref) <= 0.02 * ref
    return ok, f"got {g:.4f}, Black-Scholes {ref:.4f}"

