double mcCall(double S, double K, double r, double sigma, double T, int n, uint64_t seed) {
    mt19937_64 rng(seed);
    normal_distribution<double> Z(0.0, 1.0);
    const double drift = (r - 0.5 * sigma * sigma) * T, vol = sigma * sqrt(T);
    double total = 0.0;
    const int half = n / 2;
    for (int i = 0; i < half; ++i) {
        double z = Z(rng);
        total += max(S * exp(drift + vol * z) - K, 0.0) + max(S * exp(drift - vol * z) - K, 0.0);
    }
