class LRUCache {
    size_t cap;
    list<pair<int,int>> order;                                  // front = most recent
    unordered_map<int, list<pair<int,int>>::iterator> pos;
public:
    explicit LRUCache(size_t c) : cap(c) {}
    int get(int key) {
        auto it = pos.find(key);
        if (it == pos.end()) return -1;
        order.splice(order.begin(), order, it->second);
        return it->second->second;
    }
    void put(int key, int value) {
        auto it = pos.find(key);
        if (it != pos.end()) { it->second->second = value; order.splice(order.begin(), order, it->second); return; }
        order.emplace_front(key, value); pos[key] = order.begin();
        if (pos.size() > cap) { pos.erase(order.back().first); order.pop_back(); }
    }
};

