vector<long long> schedule(const vector<long long>& d, int k) {
    using P = pair<long long, int>;
    priority_queue<P, vector<P>, greater<P>> freeAt;
    for (int w = 0; w < k; ++w) freeAt.emplace(0, w);
    vector<long long> out;
    for (long long x : d) {
        auto [t, w] = freeAt.top(); freeAt.pop();
        out.push_back(t + x);
        freeAt.emplace(t + x, w);
    }
    return out;
}

int main() {
    check("sample", schedule({3, 1, 2, 2}, 2), vector<long long>{3, 1, 3, 5});
    check("one worker", schedule({5, 5, 5}, 1), vector<long long>{5, 10, 15});
    return fails;
}

